package com.metcoffee.service;
import java.util.*; import org.springframework.stereotype.Service; import com.metcoffee.dto.ProductoDTO; import com.metcoffee.model.Producto; import com.metcoffee.repository.ProductoRepository;
@Service public class CatalogoService {private final ProductoRepository productos; public CatalogoService(ProductoRepository p){productos=p;} public List<ProductoDTO> consultar(){return productos.findByActivoTrue().stream().map(this::dto).toList();} public List<ProductoDTO> novedades(){return productos.findByActivoTrueAndNovedadTrue().stream().map(this::dto).toList();} public ProductoDTO detalle(String id){return dto(productos.findById(id).filter(Producto::isActivo).orElseThrow(()->new IllegalArgumentException("Producto no encontrado")));} private ProductoDTO dto(Producto p){return new ProductoDTO(p.getId(),p.getNombre(),p.getOrigen(),p.getPerfil(),p.getImagen(),p.getPrecioBase(),p.getStockGramos(),p.isNovedad(),p.isActivo());}}
